const {skills,projects,lessons}=window.TOOLKIT;
const $=s=>document.querySelector(s),main=$('#main');
const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',skills:'m14 3-9 11h7l-2 7 9-12h-7l2-6',projects:'M3 7h7l2 3h9v10H3V7Zm0 0V4h7l2 3h9v3',lessons:'M12 5v16M12 5C8 2 4 3 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-3-1-6-2-10 1',arrow:'M5 12h14m-6-6 6 6-6 6',back:'M19 12H5m6-6-6 6 6 6',check:'m5 12 4 4L19 6',idea:'M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0l-1 4H9l-1-4',code:'m8 5-6 7 6 7m8-14 6 7-6 7',debug:'M8 9h8v6a4 4 0 0 1-8 0V9Zm1-3h6M5 10H2m20 0h-3M5 15H2m20 0h-3M9 3l1 3m5-3-1 3'};
const icon=name=>`<svg class="icon icon-${name}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.arrow}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const level=s=>`<span class="level ${s}">${s}</span>`;
let page='home',selected='',tab='learn',step=0,intent=0,filter='All',query='',toastTimer,installPrompt;
const intents=[{label:'I have an idea',title:'Find your starting point.',text:'Turn something you care about into a small project you can actually finish.',skill:'idea',symbol:'idea',steps:['Notice a need','Explore','Choose']},{label:'I’m ready to build',title:'Make the first version.',text:'Choose one useful feature. Get a clear plan, understandable code, and a way to test it.',skill:'app',symbol:'code',steps:['Plan','Build','Test']},{label:'I’m stuck',title:'Find the next small fix.',text:'Describe what should happen and what actually happens. Investigate one cause at a time.',skill:'debug',symbol:'debug',steps:['Describe','Investigate','Fix']}];
$('#nav').innerHTML=['home','skills','projects','lessons'].map(p=>`<a class="nav-link" href="#${p}" data-nav="${p}">${icon(p)}<span>${p[0].toUpperCase()+p.slice(1)}</span></a>`).join('');
function notify(message){clearTimeout(toastTimer);$('#status').textContent=message;$('#status').classList.add('show');toastTimer=setTimeout(()=>$('#status').classList.remove('show'),3500)}
function go(p,id=''){location.hash=p+(id?'/'+id:'')}
function route(){let [p,id]=location.hash.slice(1).split('/');p=({resources:'lessons',pathways:'help',workflow:'help','install-help':'help'})[p]||p||'home';if(!['home','skills','projects','lessons','help'].includes(p))p='home';if(page!==p){filter='All';query=''}page=p;selected=id||'';tab='learn';step=0;render();main.scrollTop=0;main.focus({preventScroll:true})}
function heading(title,desc,count=''){return `<div class="view-head"><div><h1>${title}</h1><p>${desc}</p></div>${count?`<span class="count">${count}</span>`:''}</div>`}
function render(){document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#location').textContent=page==='home'?'Xavier’s AI Toolkit':page==='help'?'Toolkit guide':`Workspace / ${page[0].toUpperCase()+page.slice(1)}`;
 if(page==='home')renderHome();else if(page==='help')renderHelp();else renderWorkbench();}
function renderHome(){main.innerHTML=`<div class="view home"><div class="home-intro"><p>Your ideas. Your next move.</p><span>Made for student builders</span></div><div class="launch"><div><h1>Big ideas.<br><span>Small first steps.</span></h1><p class="launch-lead">A little guidance goes a long way. Where would you like to start?</p><div class="intent-list" aria-label="Choose your starting point">${intents.map((x,i)=>`<button class="intent" data-intent="${i}" aria-pressed="${i===intent}"><span class="intent-label">${icon(x.symbol)}${x.label}</span>${icon('arrow')}</button>`).join('')}</div></div><div class="starter" id="starter"></div></div><div class="home-links"><a class="home-link" href="#skills"><div><strong>Find a skill</strong><small>10 prompts to make your own</small></div>${icon('arrow')}</a><a class="home-link" href="#projects"><div><strong>Build a project</strong><small>3 hands-on starting points</small></div>${icon('arrow')}</a><a class="home-link" href="#lessons"><div><strong>Learn the method</strong><small>6 lessons from original sources</small></div>${icon('arrow')}</a></div><button class="rail-help help-mobile" style="display:none;color:#4c419e" data-help>New here? See how it works</button></div>`;renderStarter(false);}
function renderStarter(animate=true){const x=intents[intent];$('#starter').innerHTML=`<div class="starter-top"><strong>Your suggested next move</strong><span class="motion-scene" aria-hidden="true"><span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><span class="starter-symbol symbol-${x.symbol}">${icon(x.symbol)}</span><span class="scene-spark spark-one">+</span><span class="scene-spark spark-two">+</span></span></div><div class="starter-content"><h2>${x.title}</h2><p>${x.text}</p><div class="starter-flow">${x.steps.map((s,i)=>`${i?icon('arrow'):''}<span style="--step:${i}">${s}</span>`).join('')}</div></div><a class="primary" href="#skills/${x.skill}">Open ${esc(skills.find(s=>s.id===x.skill).title)}${icon('arrow')}</a>`;observeScene();if(animate&&!reduced())$('#starter .starter-content').animate([{opacity:.2,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:240,easing:'cubic-bezier(.16,1,.3,1)'});document.querySelectorAll('[data-intent]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.intent===intent)));}
function items(){return page==='skills'?skills:page==='lessons'?lessons:Object.entries(projects).map(([id,p])=>({id,...p}))}
function renderWorkbench(){const titles={skills:['Your skill library','Choose a skill. Personalize the prompt. Make it yours.','10 skills'],projects:['Build something real','One project, one manageable step at a time.','3 projects'],lessons:['Learn from the best','Useful ideas from original sources, rewritten for student builders.','6 lessons']};let [title,desc,count]=titles[page];main.innerHTML=`<div class="view">${heading(title,desc,count)}<div class="workbench ${selected?'has-selection':''}"><div class="collection"><label class="sr-label" for="search" style="display:block;font-size:12px;margin-bottom:8px">Search ${page}</label><input id="search" class="search" type="search" placeholder="${page==='skills'?'Try “design” or “debug”':page==='lessons'?'Find a topic…':'Find a project…'}" value="${esc(query)}"><div class="filters" aria-label="Filter by experience">${['All','Explorer','Builder','Innovator'].map(l=>`<button class="filter ${filter===l?'active':''}" data-filter="${l}" aria-pressed="${filter===l}">${l}</button>`).join('')}</div><div class="item-list" id="item-list"></div></div><article class="detail" id="detail" aria-label="Selected ${page==='skills'?'skill':page==='lessons'?'lesson':'project'}"></article></div></div>`;renderList();$('#search').addEventListener('input',e=>{query=e.target.value;renderList()});}
function renderList(){const all=items(),shown=all.filter(s=>(filter==='All'||s.level===filter)&&`${s.title} ${s.desc||s.takeaway} ${s.level}`.toLowerCase().includes(query.toLowerCase().trim()));const active=shown.find(s=>s.id===selected)||shown[0];$('#item-list').innerHTML=shown.length?shown.map(s=>`<button class="item ${active?.id===s.id?'selected':''}" data-item="${s.id}" aria-pressed="${active?.id===s.id}"><span><strong>${esc(s.title)}</strong><small>${s.level}</small></span>${icon('arrow')}</button>`).join(''):`<p class="empty">No matches. Try another search or choose All.</p>`;if(active)renderDetail(active);else $('#detail').innerHTML='<h2>No matching items</h2><p class="desc">Change your search or level to see more options.</p>';}
function renderDetail(s){const top=`<div class="detail-head">${level(s.level)}<button class="back" data-back>${icon('back')}All ${page}</button></div><h2>${esc(s.title)}</h2>`;
 if(page==='skills'){$('#detail').innerHTML=top+`<p class="desc">${esc(s.desc)}</p><h3>Your starter prompt</h3><div class="prompt" id="active-prompt">${esc(s.prompt)}</div><div class="detail-actions"><button class="primary" data-copy>Copy prompt ${icon('arrow')}</button><button class="secondary" data-next="${s.id}">Next skill</button></div><p class="note">Replace the [brackets] with your details. Try it in your AI assistant, review the answer, and test the result yourself. Keep passwords and private student data out of prompts.</p>`;}
 else if(page==='lessons'){$('#detail').innerHTML=top+`<p class="desc">${esc(s.takeaway)}</p><div class="segmented" aria-label="Lesson sections">${[['learn','Key lessons'],['try','Try it'],['prompt','Use the prompt']].map(([id,label])=>`<button class="segment ${tab===id?'active':''}" data-tab="${id}" data-current="${s.id}" aria-pressed="${tab===id}">${label}</button>`).join('')}</div><div class="lesson-pane">${tab==='learn'?`<ul>${s.points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:tab==='try'?`<h3>Try it, ${esc(s.level)}</h3><p>${esc(s.exercise)}</p><div class="task-box"><strong>Finish with</strong><p>${esc(s.done)}</p></div>`:`<div class="prompt" id="active-prompt">${esc(s.prompt)}</div><button class="primary" data-copy>Copy prompt ${icon('arrow')}</button><p class="note">Personalize the brackets before using this prompt.</p>`}</div><div class="source">${s.sourceHtml}${s.extra}</div><p class="note">Exercises and prompts are Toolkit adaptations. Original ideas remain credited. Reviewed October 25, 2026.</p>`;}
 else {const labels=['The brief','Make a plan','Build & test'];$('#detail').innerHTML=top+`<p class="desc">${esc(s.desc)}</p><div class="segmented" aria-label="Project steps">${labels.map((l,i)=>`<button class="segment ${step===i?'active':''}" data-step="${i}" data-current="${s.id}" aria-pressed="${step===i}">${l}</button>`).join('')}</div><div class="lesson-pane">${step===0?`<h3>Start with your version</h3><p>Choose a topic you care about and someone who would use it. Keep the first version small enough to finish.</p><div class="task-box"><strong>Your first decision</strong><p>Who is this for, and what is the one thing they should be able to do?</p></div>`:step===1?`<h3>Work with a coding coach</h3><div class="prompt" id="active-prompt">${esc(s.prompt)}</div><button class="primary" data-copy>Copy project prompt ${icon('arrow')}</button>`:`<h3>Make it work. Then make it yours.</h3><ol><li>Build the smallest working version.</li><li>Try the main action, missing inputs, and restarting.</li><li>Check it on a phone and with a keyboard.</li><li>Ask someone to try it. Record one change their feedback suggests.</li><li>Explain what you built, how AI helped, and what still needs work.</li></ol><p class="note">These steps are a guide, not a claim that your project has passed testing.</p>`}</div><div class="step-nav"><button class="secondary" data-step="${step-1}" data-current="${s.id}" ${step===0?'disabled':''}>Back</button><span>Step ${step+1} of 3</span><button class="secondary" data-step="${step+1}" data-current="${s.id}" ${step===2?'disabled':''}>Next</button></div>`;}}
function renderHelp(){main.innerHTML=`<div class="view help-layout">${heading('A little guidance. A clear next step.','Use this space your way. You do not need to finish everything in order.')}<details open><summary>Find your starting level</summary><p><strong>Explorer:</strong> new to AI; start with ideas, prompts, and your first webpage.<br><strong>Builder:</strong> plan and make a useful app, improve the design, and debug.<br><strong>Innovator:</strong> review your work, prepare a responsible launch, and reuse a tested workflow.</p></details><details><summary>Five habits for better projects</summary><ol><li>Write the brief: define what success looks like.</li><li>Focus on one feature at a time.</li><li>Test what actually happens.</li><li>Save working code in GitHub checkpoints.</li><li>Explain your choices and understand AI-generated code.</li></ol></details><details><summary>Install the toolkit and use it offline</summary><p><strong>iPhone / iPad:</strong> open in Safari, tap Share, then Add to Home Screen.<br><strong>Android:</strong> open in Chrome and choose Install app from its menu.<br><strong>Desktop:</strong> use the installation option in Chrome or Edge.</p><p>Once loaded online and cached, the core skills, lessons and project guides can be used offline. External source links need internet.</p></details><details><summary>Sources, attribution and privacy</summary><p>The six lessons link to their original authors. Exercises and prompts are Toolkit adaptations. Check original documentation and licenses before reusing materials. Do not paste passwords or private student data into prompts.</p><p><a href="https://github.com/xavierwang2009/AI-Toolkit" target="_blank" rel="noopener">Open the source repository</a></p></details><p class="note">Xavier’s AI Toolkit · CYF DigitalFuture Youth Creator Initiative</p></div>`;}
main.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-intent')){intent=+b.dataset.intent;renderStarter();}
 if(b.dataset.item)go(page,b.dataset.item);
 if(b.hasAttribute('data-back'))go(page);
 if(b.dataset.filter){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter===filter);x.setAttribute('aria-pressed',String(x.dataset.filter===filter))});tab='learn';step=0;renderList();}
 if(b.dataset.tab){tab=b.dataset.tab;renderDetail(items().find(x=>x.id===b.dataset.current));const focusTarget=b.dataset.tab?`[data-tab="${tab}"]`:`.segment[data-step="${step}"]`;$(focusTarget)?.focus();}
 if(b.hasAttribute('data-step')){step=Math.max(0,Math.min(2,+b.dataset.step));renderDetail(items().find(x=>x.id===b.dataset.current));const focusTarget=b.dataset.tab?`[data-tab="${tab}"]`:`.segment[data-step="${step}"]`;$(focusTarget)?.focus();}
 if(b.dataset.next){const list=skills.filter(s=>(filter==='All'||s.level===filter)&&`${s.title} ${s.desc} ${s.level}`.toLowerCase().includes(query.toLowerCase().trim()));const i=list.findIndex(s=>s.id===b.dataset.next);if(list.length>1)go('skills',list[(i+1)%list.length].id);else notify('This is the only matching skill. Change the search or level to explore more.');}
 if(b.hasAttribute('data-help'))go('help');
 if(b.hasAttribute('data-copy')){const p=$('#active-prompt');try{await navigator.clipboard.writeText(p.textContent);b.innerHTML=`Copied ${icon('check')}`;b.classList.add('copy-confirmed');notify('Prompt copied. Replace the brackets with your own details.')}catch{const r=document.createRange();r.selectNodeContents(p);const s=window.getSelection();s.removeAllRanges();s.addRange(r);notify('Prompt selected. Use your device’s Copy command.')}}
});
function reduced(){return document.body.classList.contains('no-motion')||matchMedia('(prefers-reduced-motion: reduce)').matches}
const sceneObserver=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('motion-paused',!e.isIntersecting)),{threshold:.15});
function observeScene(){sceneObserver.disconnect();const scene=$('#starter');if(scene)sceneObserver.observe(scene)}
document.addEventListener('visibilitychange',()=>document.body.classList.toggle('page-hidden',document.hidden));
$('#motion').addEventListener('click',()=>{const off=document.body.classList.toggle('no-motion');$('#motion').textContent=off?'Motion off':'Motion on';$('#motion').setAttribute('aria-pressed',String(off));if(off)document.getAnimations().forEach(a=>a.cancel())});
if(matchMedia('(prefers-reduced-motion: reduce)').matches){$('#motion').textContent='Reduced motion';$('#motion').disabled=true}
$('#help-button').onclick=()=>go('help');
window.addEventListener('hashchange',route);route();
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#install').hidden=true}};
if('serviceWorker'in navigator){let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshing){refreshing=true;location.reload()}});window.addEventListener('load',async()=>{try{const r=await navigator.serviceWorker.register('/sw.js');const check=()=>{$('#update').hidden=!(r.waiting&&navigator.serviceWorker.controller)};check();r.addEventListener('updatefound',()=>r.installing?.addEventListener('statechange',check));$('#update').onclick=()=>{if(r.waiting)r.waiting.postMessage({type:'SKIP_WAITING'})}}catch{}})}

document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus()});
